import React, { useState } from "react";

export default function ChatWindow({ report }) {
  const [messages, setMessages] = useState([
    {
      text: `Hello ${report.reporter.split(" ")[0]}, we have received your report and our team is reviewing the location.`,
      admin: true,
      time: "09:58",
    },
    {
      text: "Thank you. I can share more details if needed.",
      admin: false,
      time: "10:04",
    },
  ]);
  const [draft, setDraft] = useState("");
  const send = (event) => {
    event.preventDefault();
    if (!draft.trim()) return;
    setMessages((current) => [
      ...current,
      {
        text: draft.trim(),
        admin: true,
        time: new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
      },
    ]);
    setDraft("");
  };
  return (
    <section className="panel chat-page">
      <div className="chat-contact">
        <span className="avatar">
          {report.reporter
            .split(" ")
            .map((part) => part[0])
            .join("")}
        </span>
        <div>
          <b>{report.reporter}</b>
          <small>Citizen · Case {report.id}</small>
        </div>
        <span className="available">
          <i /> Case open
        </span>
      </div>
      <div className="chat-thread">
        <div className="chat-day">TODAY</div>
        {messages.map((item, index) => (
          <div
            className={`message-row ${item.admin ? "outgoing" : ""}`}
            key={`${item.time}-${index}`}
          >
            <div className="message-bubble">
              <p>{item.text}</p>
              <small>
                {item.time}
                {item.admin ? " · You" : ""}
              </small>
            </div>
          </div>
        ))}
      </div>
      <form className="chat-form" onSubmit={send}>
        <input
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Write a message to the citizen…"
        />
        <button className="primary" type="submit">
          Send <span>➤</span>
        </button>
      </form>
    </section>
  );
}
